import{_ as a,a as r}from"./chunks/b7df1ad96d20e999caa8.zJmjEnrD.js";import{_ as l,C as i,o,c as n,j as e,a as h,E as s,a6 as c}from"./chunks/framework.CnPv4DE1.js";const q=JSON.parse('{"title":"解决你自己的问题，然后出售解决方案","description":"","frontmatter":{"title":"解决你自己的问题，然后出售解决方案","originalTitle":"Solve Your Own Problems & Sell The Solution","date":"2023-04-22","originalUrl":"https://thedankoe.com/letters/the-self-reliant-career-path-how-to-generate-independent-income/","minutes":10,"sourceHash":"cea008f4ba980e19b68ed4f6e8747a5986c7c7fe580ca7c8efe8383c6cc1452f","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-self-reliant-career-path-how-to-generate-independent-income/"}]]},"headers":[],"relativePath":"letters/the-self-reliant-career-path-how-to-generate-independent-income.md","filePath":"letters/the-self-reliant-career-path-how-to-generate-independent-income.md"}'),m={name:"letters/the-self-reliant-career-path-how-to-generate-independent-income.md"};function d(f,p,u,_,b,g){const t=i("ArticleMeta");return o(),n("div",null,[p[0]||(p[0]=e("h1",{id:"解决你自己的问题-然后出售解决方案",tabindex:"-1"},[h("解决你自己的问题，然后出售解决方案 "),e("a",{class:"header-anchor",href:"#解决你自己的问题-然后出售解决方案","aria-label":'Permalink to "解决你自己的问题，然后出售解决方案"'},"​")],-1)),s(t),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/GmHQGVD7KRQ?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>创作者经济是一个去中心化的社会，在这里人们可以学习、教导他人，并为自己创造更美好的生活。</p><p>在过去的十年里，我认识到了这一点。</p><p>当我还是个孩子的时候，我不相信学校系统（或我的父母）能为我提供充分度过一生所需的必要知识。</p><p>相反，我消费了来自 YouTuber、博主和社交媒体账号的内容，他们在教授关于健身、商业和哲学的知识。</p><p>我购买了价格亲民的课程，它们教给我的东西比我那昂贵得离谱的大学学位还要多。</p><p>我的大学学位让我得到了一份年薪 6 万美元的工作。</p><p>我的互联网学习则为我建立了一家企业，让我能够在这辈子做任何我想做的事。</p><p>教育只是创作者经济的一个方面。</p><p>我将其视为一个自给自足的乌托邦，是人类欲望与进化的产物。</p><p>我有一个专门卖鞋子的人。</p><p>我有一个专门卖厨具的人。</p><p>我有一个专门卖防蓝光眼镜的人。</p><p>我有一个专门卖服饰的人。</p><p>我有一个专门卖咖啡和补剂的人。</p><p>我有一个专门卖新鲜香草、牛奶和肉类的人。</p><p>所有这些都有一种底层的理念，比当今那些只想掏空你钱包的肤浅品牌和巨型企业更有深度。</p><p>这个帖子就是我所表达意思的一个绝佳例子：</p><blockquote><p>这就是为什么我制作了 Sol 短裤\\</p><p>一款经典的、短内缝的 100% 纯棉短裤，它灵活、舒适，无论上身搭配什么看起来都很时髦。\\</p><p>因为找不到这样的短裤，所以我自己做了一条。<a href="https://t.co/vB85NhzpCH" target="_blank" rel="noreferrer">https://t.co/vB85NhzpCH</a></p><p>— 🌞 Sol Brah 🌞 (@SolBrah) <a href="https://twitter.com/SolBrah/status/1649604730426126338?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">April 22, 2023</a></p></blockquote><p>当然，在相关领域，我也有许多可以从中获取特定知识的个人。</p><p>如果我想学习股票或房地产投资，我可以用考取学位成本的一小部分来获取这些知识。而且我会得到 10 倍的效果，因为教这些知识的人确实取得了实际成果。</p><p>创作者经济就是你在其中可以：</p><ul><li>找到志同道合的人</li><li>打造你自己的社区</li><li>为该社区提供价值</li><li>为你的贡献获得报酬</li></ul><p>我的建议是从我们在以前信件中学到的东西开始。</p><p>通过追求你的目标来开启一项教育业务（因为它的启动成本极低，而且利润空间巨大）。</p><p>为你自己创造一份独立的收入。</p><p>然后，建立一个你<em>真正</em>想要建立的企业。</p><p>我的小型教育一人企业每年大约赚 150 万美元。</p><p>我现在正在写一本书，开发软件，并规划我想给世界留下的真正影响。我有资金和资源来做这件事，但这仅仅是因为我是从我现有的东西起步的。</p><p>我没有幻想着去建立一家估值十亿美元的公司，然后让自己陷入压倒性的压力和焦虑之中无法动弹。</p><p>那样做只会让你取得 0 进展。</p><p>附：这种商业模式（解决你自己的问题并出售解决方案）正是我在 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学（Digital Economics）</a> 里致力于帮助大家实现的。</p><h2 id="为了利润与目标解决你的问题" tabindex="-1">为了利润与目标解决你的问题 <a class="header-anchor" href="#为了利润与目标解决你的问题" aria-label="Permalink to &quot;为了利润与目标解决你的问题&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>我的整个商业旅程都是自私的。</p><p>我所做的一切就是为自己构建，写给自己，并卖给自己。</p><p>当你本身就是细分领域时，饱和与竞争就不复存在了。</p><p>如果你想从你的目标中获利：</p><ol><li>找出你生活中的一个问题</li><li>设定一个目标以揭示你当前的意图</li><li>尝试不同的解决方案</li><li>找到行之有效的方法并创造你自己的方案</li><li>公开谈论你的旅程</li><li>贴上价格标签，提供你的解决方案</li></ol><p>重复这个过程一直是我生命中的指路明灯。</p><p>从我记事起，我就一直有一个要构建的项目。</p><p>项目是实现你的目标（或目的）的一种有组织的方式。</p><p>几年前，我在生产力方面遇到了困难。</p><p>我很难集中注意力，而且我知道我可以做得更多。</p><p>那就是我意识到的问题。</p><p>所以，我把修复我生活中的那个部分作为我的目标。</p><p>我看 YouTube 视频，购买补剂，并订购了几种不同的计划表和日记本。</p><p>我坚决要解决这个问题，所以我尝试了我得到的每一条建议。</p><p>几个月后，我取得了一些令人难以置信的成果。</p><p>于是，我坐下来去创建一个能完美契合<em>我</em>的可持续生产力解决方案（因为我尝试过的其他方法总有一些小瑕疵）。</p><p>就在那时，我设计并推出了数字版的 Power Planner。</p><p>当时我没有很多粉丝，但我非常喜欢靠我的生产力知识谋生的想法。所以，我：</p><ul><li>写下我所知道的关于生产力的内容</li><li>用适当的策略积累了粉丝</li><li>将数字计划表作为免费下载项进行推广</li><li>在免费下载的内容中加入了教育资源</li></ul><p>人们很喜欢它。</p><p>所以，我更进了一步，推出了实体版的计划表。</p><p>尽管现在情况有所不同，但我整个的成功都建立在解决自己的问题并出售解决方案上。</p><p>我通过学习网页设计解决了我的职业问题（所以我做了一门课程）。</p><p>我通过做自由职业大获成功解决了我的金钱问题（所以我又做了一门课程）。</p><p>然后，Modern Mastery 诞生了，因为我建立了一个我原本自己就想要的社区和学习平台。</p><p>现在，我正在写一本书并开发一款软件，我可以将它们卖给年轻时的自己（以帮助他更快地实现目标）。</p><p>就这么简单。</p><p>每个人都是创业者。</p><p>只是有些人因为他们所解决的问题而获得了报酬。</p><h2 id="自力更生的职业道路-如何开始" tabindex="-1">自力更生的职业道路（如何开始） <a class="header-anchor" href="#自力更生的职业道路-如何开始" aria-label="Permalink to &quot;自力更生的职业道路（如何开始）&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><blockquote><p>这个星球上差不多有 70 亿人。我希望有一天，这里也会有将近 70 亿家公司。 <em>——</em> 纳瓦尔 (Naval)</p></blockquote><p>未来的工作就是玩耍，每个人都将成为创业者。</p><p>每个人都会被迫创造、贡献，并向他们的社区提供价值，否则他们的生存之道就会枯竭。</p><p>人工智能预示着这一现实。</p><p>自动化预示着这一现实。</p><p>互联网上的大多数事物都在预示着这一现实。</p><p>即使这对大多数人来说并没有成为现实，但对你而言可以。</p><h3 id="_1-赚钱的兴趣" tabindex="-1">1) 赚钱的兴趣 <a class="header-anchor" href="#_1-赚钱的兴趣" aria-label="Permalink to &quot;1) 赚钱的兴趣&quot;">​</a></h3><p>我们从人生方向开始。</p><p>你需要一个愿景、各种目标以及你每天都能执行的优先任务。</p><p>这就是你在此生中获取经验的方式。</p><p>这就是你获取知识、技能的方式，以及明确如何获取这两者的方向，并且你可以把这些传递给走在同一条路上的人。</p><p>所有急迫的问题（在你和别人的生活中）都落在永恒的市场中：健康、财富和人际关系。</p><p>自我提升就是去解决你在这些领域里的自身问题。</p><p>商业就是为这些领域里的问题提供解决方案。</p><p>仅仅通过：</p><ul><li>设定一个有明确意图的目标来提升自己</li><li>自我教育并获取关于头脑、身体和商业的技能</li><li>让你的好奇心引导你选择和创造哪些方法</li></ul><p>你将拥有必要的经验去帮助他人，并从充满目标感的生活中获利。</p><p>在这里，好奇心是一个至关重要的接触点。</p><p>让你与众不同的是，你有能力找到那些能让你获得结果的知识组合。</p><p>在商业领域，有些人可能对电子商务或倒卖网站感到好奇。</p><p>其他人可能对个人品牌和数字产品感到好奇。</p><p>在健康领域，有些人可能对运动和巅峰表现感到好奇。</p><p>其他人可能对健美和生物黑客（biohacking）感到好奇。</p><p>我们常常认为自己做的事情和所有人一样。</p><p>但你的故事截然不同。</p><p>每个人都必须在同样的永恒市场中追求目标。你无法逃避这一点。但你追求这些目标的方式可以是专属于你自己的，而这正是让你的经验变得有利可图的原因。</p><h3 id="_2-从项目到产品" tabindex="-1"><strong>2) 从项目到产品</strong> <a class="header-anchor" href="#_2-从项目到产品" aria-label="Permalink to &quot;**2) 从项目到产品**&quot;">​</a></h3><p>如果你不知道该卖什么，那就卖你在旅途中曾经想要的东西，或者你现在想要却找不到的东西。</p><p>当你开始追求一个目标时，实现它的最佳方式是：</p><ul><li>学习基础知识以获得清晰度</li><li>开始一个真实世界的项目，这样你就不会陷入“教程地狱”</li><li>推进这个项目，直到你发现一个问题</li><li>购买课程、辅导，或研究互联网内容来寻找解决方案</li><li>应用你学到的一切，直到项目完成</li></ul><p>“项目”听起来似乎不适用于生活的各个领域，但请听我把话说完。</p><p>当你开始改善健康状况时，只有当你把它变成一个可衡量的个人项目时，你才能取得进展。</p><p>你去健身房。</p><p>你写下你的训练计划。</p><p>你记录你的每一次举重。</p><p>如果你没有看到进展，你就会去研究并找到你知识中的空白。</p><p>也许是营养问题拖了你的后腿？</p><p>是时候追踪你的卡路里摄入了。</p><p>看到体型有了改善，但精力却没有跟上？</p><p>也许你掉进了一个深奥的兔子洞，了解牛肝是这个星球上营养最密集的食物。</p><p>于是，你去尝试它并记录下结果。</p><p>当你把你生活的每个领域都当作一个以目标为导向的项目时，你会被要求去进行实验。</p><p>通过自我实验，你创造了一套独特的经验，你可以将它们传递给别人。</p><p>在营销中，你在出售目标（目标 = 目的 = 期望的结果）。</p><p>你在出售追求那个目标所带来的生活方式的益处。</p><p>在健康领域，有些人可能会把跑步产品卖给<em>那些想要建立健康的社交圈并融入社区的 20-30 岁年轻人</em><em>。</em></p><p>另一些人可能会把一套力量训练计划卖给那些只想每周去 3 天健身房就练得一身肌肉的商业老哥。这样他们就能既有钱又有肌肉，从而过上充满乐趣的生活。谁会不买单呢（如果他们对这款产品的理念产生共鸣）？</p><p>我的写作产品 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 小时作家（2 Hour Writer）</a>，就是我做个人品牌和通过数字写作获得数百万粉丝的独特经验。</p><p>在长达 2-3 年的时间里，我尝试了创意生成、通讯（newsletter）写作以及社交媒体内容。</p><p>你不必等那么久。</p><p>实际上我建议立即发布。</p><p>你需要<em>数据</em>和<em>反馈</em>来了解如何让你的产品变得更好。</p><p>你从充满目标感的生活中获得的益处，就是你帮助人们过上更好生活的营销火力。</p><p>也就是说，你通过自我实验所锻造出的底层理念，就是你如何从追求中产生创造性收入的方式。</p><h3 id="_3-个人分发中心" tabindex="-1">3) 个人分发中心 <a class="header-anchor" href="#_3-个人分发中心" aria-label="Permalink to &quot;3) 个人分发中心&quot;">​</a></h3><p>到目前为止，这一切听起来都很棒。</p><ol><li>研究你的兴趣来实现你的目标</li><li>通过个人项目进行实验以获得结果</li><li>将该项目变成一个你可以带着目标去出售的产品</li></ol><p>但大多数人都在那里卡住了。</p><p>他们没有意识到，你需要同时拥有产品和<em>人</em>才能真正赚到钱。</p><p>你必须建立<em>分发渠道</em>。</p><p>这不是可有可无的。</p><p>我最喜欢的做法是建立个人品牌。</p><p>一方面，因为这正在成为一种必需品。</p><p>品牌、公司和雇主同样都在基于你的公开简历（你的个人主页）进行招聘。</p><p>第二，你积累的关注者就是杠杆。</p><p>随着你人生的转变，你也可以随之转型，并推销任何你想卖的东西（<a href="https://thedankoe.com/the-most-profitable-niche-is-you-how-to-create-your-niche/" target="_blank" rel="noreferrer">只要你别把自己困在一个狭窄的细分领域里</a>）。</p><p>第三，大多数其他形式的分发渠道最终会让你一无所有。</p><p>付费广告和陌生触达（cold outreach）非常强大，但是当你停止做这些时会发生什么？</p><p>你有一路走来建立起的受众群体或电子邮件列表吗？</p><p>你能休息一下吗？</p><p>你能在你的品牌背后培养出一种有意义的哲学，并且在销售的产品上不受限制吗？</p><p>也许能，但这不太可能。</p><p>通过以下方式建立一个个人分发中心：</p><ul><li>传授你在追求目标过程中学到的经验教训</li><li>写下你的想法、信念和观点，使自己与众不同</li><li>以有说服力的方式教授你所学到的知识</li></ul><p>真的就是这样。</p><p>其中有很多技术细节和<a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">细致入微的社交媒体增长策略</a>……但那是一个你可以自己去尝试和实验的目标与项目。</p><p>（这就是你开始学习每一项有市场价值的技能的方式：通过建立你的企业并将你学到的知识应用其中）。</p><p>这就是未来的职业道路。</p><p>这就是你如何将几乎所有学到的东西变现的方式。</p><p>这就是你如何仅凭生活本身就能获得报酬的方式。</p><p>未来属于那些传授自己宝贵经验以改善他人生活的人。</p><p>所有最顶尖的企业都是这么做的，只要看看你看到的下一条社交媒体帖子（以创作者而非消费者的视角），你就可以自己验证这一点。</p><p>加入创作者经济这个自给自足且不断发展的乌托邦吧，以后你会感谢我的。</p><p>– Dan</p><hr><p><a href="/en/letters/the-self-reliant-career-path-how-to-generate-independent-income">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',152))])}const P=l(m,[["render",d]]);export{q as __pageData,P as default};
